-- Futurevision Technologies | initial production-oriented schema
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.roles(user_id uuid not null references public.profiles(id) on delete cascade,role text not null check(role in('student','instructor','admin','guardian')),created_at timestamptz not null default now(),primary key(user_id,role));
create or replace function public.has_role(target uuid,required text) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.roles where user_id=target and role=required)$$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select public.has_role(auth.uid(),'admin')$$;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'instructor')$$;
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''));insert into public.roles(user_id,role) values(new.id,'student') on conflict do nothing;return new;end$$;
drop trigger if exists auth_user_profile on auth.users;
create trigger auth_user_profile after insert on auth.users for each row execute procedure public.new_profile();
create table if not exists public.courses(id uuid primary key default gen_random_uuid(),code text unique not null,title text not null,description text not null default '',level text not null default 'Beginner',published boolean not null default false,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.modules(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,title text not null,sort_order int not null default 0);
create table if not exists public.lessons(id uuid primary key default gen_random_uuid(),module_id uuid not null references public.modules(id) on delete cascade,title text not null,content text not null default '',sort_order int not null default 0,published boolean not null default false);
create table if not exists public.enrollments(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,course_id uuid not null references public.courses(id) on delete cascade,status text not null default 'active' check(status in('active','completed','withdrawn')),created_at timestamptz not null default now(),unique(student_id,course_id));
create table if not exists public.progress(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,lesson_id uuid not null references public.lessons(id) on delete cascade,completed boolean not null default false,score numeric(5,2),updated_at timestamptz not null default now(),unique(student_id,lesson_id));
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,title text not null,description text not null default '',status text not null default 'in_progress',file_path text,created_at timestamptz not null default now());
create table if not exists public.bootcamps(id uuid primary key default gen_random_uuid(),title text not null,course_code text,description text not null default '',starts_at timestamptz,ends_at timestamptz,capacity int check(capacity is null or capacity>0),published boolean not null default false);
create table if not exists public.bootcamp_enrollments(id uuid primary key default gen_random_uuid(),bootcamp_id uuid not null references public.bootcamps(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'registered',created_at timestamptz not null default now(),unique(bootcamp_id,student_id));
create table if not exists public.game_bus_sessions(id uuid primary key default gen_random_uuid(),title text not null,description text not null default '',location text,starts_at timestamptz,ends_at timestamptz,capacity int,published boolean not null default false);
create table if not exists public.game_bus_registrations(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.game_bus_sessions(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,attendance text not null default 'registered',unique(session_id,student_id));
create table if not exists public.game_scores(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,game_code text not null,score int not null default 0,xp int not null default 0,created_at timestamptz not null default now());
create table if not exists public.achievements(id uuid primary key default gen_random_uuid(),code text unique not null,title text not null,description text not null default '',xp_reward int not null default 0);
create table if not exists public.student_achievements(student_id uuid not null references public.profiles(id) on delete cascade,achievement_id uuid not null references public.achievements(id) on delete cascade,earned_at timestamptz not null default now(),primary key(student_id,achievement_id));
create table if not exists public.certificates(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,course_id uuid references public.courses(id),certificate_code text unique not null,issued_at timestamptz not null default now(),issued_by uuid references public.profiles(id));
create table if not exists public.announcements(id uuid primary key default gen_random_uuid(),title text not null,body text not null,published boolean not null default false,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,title text not null,body text not null default '',read_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.assignments(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,title text not null,instructions text not null default '',due_at timestamptz,points int not null default 100,created_by uuid references public.profiles(id));
create table if not exists public.submissions(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.assignments(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,content text not null default '',file_path text,score numeric(5,2),feedback text,submitted_at timestamptz not null default now(),unique(assignment_id,student_id));
create index if not exists enrollments_student_idx on public.enrollments(student_id);
create index if not exists progress_student_idx on public.progress(student_id);
create index if not exists notifications_user_idx on public.notifications(user_id,created_at desc);
do $$declare t text;begin foreach t in array array['profiles','roles','courses','modules','lessons','enrollments','progress','projects','bootcamps','bootcamp_enrollments','game_bus_sessions','game_bus_registrations','game_scores','achievements','student_achievements','certificates','announcements','notifications','assignments','submissions'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy "profile owner or admin read" on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy "profile owner update" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy "roles self or admin read" on public.roles for select using(user_id=auth.uid() or public.is_admin());
create policy "admin manage roles" on public.roles for all using(public.is_admin()) with check(public.is_admin());
create policy "published courses readable" on public.courses for select using(published or public.is_staff());
create policy "staff manage courses" on public.courses for all using(public.is_staff()) with check(public.is_staff());
create policy "published modules readable" on public.modules for select using(exists(select 1 from public.courses c where c.id=course_id and (c.published or public.is_staff())));
create policy "staff manage modules" on public.modules for all using(public.is_staff()) with check(public.is_staff());
create policy "published lessons readable" on public.lessons for select using(published or public.is_staff());
create policy "staff manage lessons" on public.lessons for all using(public.is_staff()) with check(public.is_staff());
create policy "student own enrollments" on public.enrollments for select using(student_id=auth.uid() or public.is_staff());
create policy "student request enrollment" on public.enrollments for insert with check(student_id=auth.uid());
create policy "staff manage enrollments" on public.enrollments for all using(public.is_staff()) with check(public.is_staff());
create policy "student own progress" on public.progress for select using(student_id=auth.uid() or public.is_staff());
create policy "student update own progress" on public.progress for insert with check(student_id=auth.uid());
create policy "student edit own progress" on public.progress for update using(student_id=auth.uid()) with check(student_id=auth.uid());
create policy "own projects" on public.projects for all using(student_id=auth.uid() or public.is_staff()) with check(student_id=auth.uid() or public.is_staff());
create policy "published bootcamps" on public.bootcamps for select using(published or public.is_staff());
create policy "staff manage bootcamps" on public.bootcamps for all using(public.is_staff()) with check(public.is_staff());
create policy "own bootcamp enrollment" on public.bootcamp_enrollments for select using(student_id=auth.uid() or public.is_staff());
create policy "register self bootcamp" on public.bootcamp_enrollments for insert with check(student_id=auth.uid());
create policy "staff manage bootcamp enrollments" on public.bootcamp_enrollments for all using(public.is_staff()) with check(public.is_staff());
create policy "published game bus sessions" on public.game_bus_sessions for select using(published or public.is_staff());
create policy "staff manage game bus sessions" on public.game_bus_sessions for all using(public.is_staff()) with check(public.is_staff());
create policy "own game bus registrations" on public.game_bus_registrations for select using(student_id=auth.uid() or public.is_staff());
create policy "register self game bus" on public.game_bus_registrations for insert with check(student_id=auth.uid());
create policy "staff manage game bus registrations" on public.game_bus_registrations for all using(public.is_staff()) with check(public.is_staff());
create policy "own scores" on public.game_scores for select using(student_id=auth.uid() or public.is_staff());
create policy "insert own scores" on public.game_scores for insert with check(student_id=auth.uid());
create policy "achievements readable" on public.achievements for select using(true);
create policy "own achievements" on public.student_achievements for select using(student_id=auth.uid() or public.is_staff());
create policy "staff award achievements" on public.student_achievements for all using(public.is_staff()) with check(public.is_staff());
create policy "own certificates" on public.certificates for select using(student_id=auth.uid() or public.is_staff());
create policy "staff issue certificates" on public.certificates for insert with check(public.is_staff());
create policy "published announcements" on public.announcements for select using(published or public.is_staff());
create policy "staff manage announcements" on public.announcements for all using(public.is_staff()) with check(public.is_staff());
create policy "own notifications" on public.notifications for select using(user_id=auth.uid() or public.is_admin());
create policy "own notification update" on public.notifications for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "enrolled students or staff read assignments" on public.assignments for select using(exists(select 1 from public.enrollments e where e.course_id=public.assignments.course_id and e.student_id=auth.uid()) or public.is_staff());
create policy "staff manage assignments" on public.assignments for all using(public.is_staff()) with check(public.is_staff());
create policy "own submissions" on public.submissions for select using(student_id=auth.uid() or public.is_staff());
create policy "submit own work" on public.submissions for insert with check(student_id=auth.uid());
create policy "update own submission" on public.submissions for update using(student_id=auth.uid() or public.is_staff()) with check(student_id=auth.uid() or public.is_staff());
-- Assign instructor/admin roles only through a trusted administrative process.
-- Review instructor course-scoped access and storage bucket policies before real student data is used.
